using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.ComponentModel;using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class DinPositionDraft{[DisplayName("Trilho (0 com coluna0 = automático)")]public int Row{get;set;}[DisplayName("Coluna (0 com trilho0 = automático)")]public int Column{get;set;}}
public sealed class EnclosureCatalogForm:Form {
readonly Project project;readonly Board board;readonly Action onChanged;List<EnclosureRating> items;readonly ComboBox catalogue=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=390};readonly ComboBox circuitPick=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=280};readonly Panel drawing=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=Color.White};readonly TextBox info=new TextBox{Dock=DockStyle.Right,Width=560,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical};public bool Changed{get;private set;}
public EnclosureCatalogForm(Project p,Board b,Action changed=null){if(p==null||b==null||!p.Boards.Contains(b))throw new InvalidDataException("Selecione um quadro.");project=p;board=b;onChanged=changed;items=EnclosureCatalog.ReferenceCatalog();if(b.EnclosureCatalogSelection!=null&&b.EnclosureCatalogSelection.Rating!=null&&!items.Any(x=>x.Reference==b.EnclosureCatalogSelection.Rating.Reference))items.Add(b.EnclosureCatalogSelection.Rating.Copy());Text="Invólucro real e ocupação frontal — "+b.Id;Size=new Size(1450,960);MinimumSize=new Size(1100,760);Font=new Font("Segoe UI",10);var actions=new FlowLayoutPanel{Dock=DockStyle.Top,Height=120};catalogue.DisplayMember="Reference";catalogue.Items.Clear();catalogue.Items.AddRange(items.Cast<object>().ToArray());catalogue.SelectedIndex=-1;actions.Controls.Add(catalogue);Add(actions,"Aplicar referência",()=>{var selected=catalogue.SelectedItem as EnclosureRating;if(selected==null)throw new InvalidDataException("Selecione referência.");ApplyRating(selected);});Add(actions,"Importar catálogo CSV",()=>{using(var d=new OpenFileDialog{Filter="Invólucros CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK){items=EnclosureCatalog.Import(d.FileName);catalogue.Items.Clear();catalogue.Items.AddRange(items.Cast<object>().ToArray());catalogue.SelectedIndex=-1;}});Add(actions,"Exportar catálogo CSV",()=>{using(var d=new SaveFileDialog{Filter="Invólucros CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK)EnclosureCatalog.Export(items,d.FileName);});circuitPick.DisplayMember="Id";circuitPick.DataSource=board.Circuits.ToList();actions.Controls.Add(circuitPick);Add(actions,"Envelope / posição",()=>EditFootprint());Add(actions,"Distribuir automaticamente",()=>AutoArrange());Add(actions,"Avaliar ocupação",()=>RefreshView());Add(actions,"Exportar frontal SVG",()=>{using(var d=new SaveFileDialog{Filter="Frontal esquemática SVG|*.svg"})if(d.ShowDialog(this)==DialogResult.OK)File.WriteAllText(d.FileName,EnclosureCatalog.Svg(project,board,Text),new System.Text.UTF8Encoding(false));});Add(actions,"Remover vínculo catálogo",()=>{board.EnclosureCatalogSelection=null;Notify();});drawing.Paint+=Draw;drawing.Resize+=(s,e)=>drawing.Invalidate();Controls.Add(drawing);Controls.Add(info);Controls.Add(actions);RefreshView();}
void Add(Control parent,string text,Action action){var button=new Button{Text=text,AutoSize=true};button.Click+=(s,e)=>{try{action();}catch(Exception ex){info.Text="Operação recusada: "+ex.Message;}};parent.Controls.Add(button);}
void Notify(){Changed=true;RefreshView();if(onChanged!=null)onChanged();}
public void ApplyRating(EnclosureRating rating){EnclosureCatalog.Apply(project,board,rating);Notify();}
public void ApplyFootprint(Circuit circuit,DinFootprint footprint,int row,int column){EnclosureCatalog.ApplyFootprint(project,board,circuit,footprint,row,column);Notify();}
public void AutoArrange(){if(Enclosures.AutoArrange(board))Notify();else RefreshView();}
public EnclosureCatalogResult Evaluate(){return EnclosureCatalog.Evaluate(project,board);}
void RefreshView(){var binding=board.EnclosureCatalogSelection;catalogue.SelectedIndex=binding==null||binding.Rating==null?-1:items.FindIndex(x=>x.Reference==binding.Rating.Reference&&x.Manufacturer==binding.Rating.Manufacturer&&x.DataVersion==binding.Rating.DataVersion);var result=Evaluate();info.Text=result.Status+"\r\n"+result.Detail+"\r\n\r\n"+String.Join("\r\n",Enclosures.Layout(board).Select(x=>x.Circuit.Id+": "+(x.Placed?"trilho "+x.Row+", coluna "+x.Column+", "+x.Modules+" módulos":"sem posição válida")));info.SelectionStart=0;info.SelectionLength=0;drawing.Invalidate();}
void EditFootprint(){var c=circuitPick.SelectedItem as Circuit;if(c==null)throw new InvalidDataException("Selecione circuito.");var data=c.DinFootprint==null?new DinFootprint{WidthModules=c.DinModules>0?c.DinModules:1}:c.DinFootprint.Copy();var position=new DinPositionDraft{Row=c.DinRow,Column=c.DinColumn};using(var form=new Form{Text="Envelope total e posição — "+c.Id,Size=new Size(900,720),MinimumSize=new Size(800,650),Font=Font,StartPosition=FormStartPosition.CenterParent}){var readers=new List<Action>();var tabs=new TabControl{Dock=DockStyle.Fill};var envelope=new TabPage("Envelope documentado");envelope.Controls.Add(TypedFields.Create(data,readers));var coordinates=new TabPage("Posição na grade");coordinates.Controls.Add(TypedFields.Create(position,readers));tabs.TabPages.AddRange(new[]{envelope,coordinates});var controls=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=55};var errors=new TextBox{Dock=DockStyle.Bottom,Height=90,Multiline=true,ReadOnly=true,Text="Largura total declarada do conjunto de dispositivos/acessórios do circuito. Quantidade não é inferida de polos. Origem/altura desenhadas são esquemáticas; confirmar profundidade e folgas na montagem real."};var ok=new Button{Text="Aplicar envelope e posição",AutoSize=true};ok.Click+=(s,e)=>{try{foreach(var read in readers)read();ApplyFootprint(c,data,position.Row,position.Column);form.DialogResult=DialogResult.OK;form.Close();}catch(Exception ex){errors.Text="Nenhuma alteração: "+ex.Message;}};controls.Controls.Add(ok);form.Controls.Add(tabs);form.Controls.Add(errors);form.Controls.Add(controls);form.ShowDialog(this);}}
void Draw(object sender,PaintEventArgs e){var spec=board.Enclosure;if(!Enclosures.SpecValid(spec))return;float scale=1.1f;drawing.AutoScrollMinSize=new Size((int)(spec.WidthMm*scale)+60,(int)(spec.HeightMm*scale)+110);var g=e.Graphics;g.TranslateTransform(drawing.AutoScrollPosition.X+25,drawing.AutoScrollPosition.Y+65);g.ScaleTransform(scale,scale);using(var font=new Font("Segoe UI",10))using(var small=new Font("Segoe UI",8)){g.DrawString("Frontal esquemática — sem cotas de montagem/furação",small,Brushes.Black,0,-45);g.DrawString(spec.WidthMm+" × "+spec.HeightMm+" mm externos; grade "+spec.Rows+" × "+spec.ModulesPerRow,font,Brushes.Black,0,-25);g.DrawRectangle(Pens.Black,0,0,(float)spec.WidthMm,(float)spec.HeightMm);double left=(spec.WidthMm-spec.ModulesPerRow*spec.ModulePitchMm)/2;for(int row=0;row<spec.Rows;row++){float y=(float)(70+row*spec.RowPitchMm);g.DrawLine(Pens.Gray,(float)left,y,(float)(left+spec.ModulesPerRow*spec.ModulePitchMm),y);}foreach(var place in Enclosures.Layout(board))if(place.Placed){float x=(float)(left+(place.Column-1)*spec.ModulePitchMm),y=(float)(30+(place.Row-1)*spec.RowPitchMm),width=(float)(place.Modules*spec.ModulePitchMm-1);bool documented=place.Circuit.DinFootprint!=null&&place.Circuit.DinModules==place.Circuit.DinFootprint.WidthModules&&place.Circuit.DinFootprint.HardwareContext==EnclosureCatalog.Hardware(place.Circuit);g.FillRectangle(documented?Brushes.LightSteelBlue:Brushes.PeachPuff,x,y,width,80);g.DrawRectangle(Pens.DarkSlateGray,x,y,width,80);g.DrawString(place.Circuit.Id+"\n"+place.Modules+"M"+(documented?"":"?"),small,Brushes.Black,new RectangleF(x+1,y+18,width-1,60));}}}
}
partial class Studio{void ConfigureEnclosureCatalog(){using(var f=new EnclosureCatalogForm(project,board,Change))f.ShowDialog(this);}}
}
